//! Bundled logos for software with no icon of its own on disk (CLI tools, apps not installed
//! in /Applications). The table is generated by `tools/gen_logos.py`.
use crate::model::App;

include!("logos_table.rs");

fn norm(s: &str) -> String {
    s.chars().filter(char::is_ascii_alphanumeric).map(|c| c.to_ascii_lowercase()).collect()
}

/// PNG bytes of the logo for this app, matched by package token or display name.
pub fn find(app: &App) -> Option<&'static [u8]> {
    let token = app.id.split_once(':').map_or(app.id.as_str(), |(_, t)| t).rsplit('/').next()?;
    // `docker-buildx` -> `docker`, `openjdk@17` -> `openjdk`.
    let base = token.split(['-', '@']).next().unwrap_or(token);
    let keys = [norm(token), norm(base), norm(&app.name)];
    LOGOS.iter().find(|(aliases, _)| keys.iter().any(|k| aliases.contains(&k.as_str()))).map(|(_, png)| *png)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn app(id: &str, name: &str) -> App {
        App { id: id.into(), name: name.into(), vendor: String::new(), from: String::new(), to: String::new(), source: crate::model::Source::Homebrew, size_mb: None, hue: 0.0, bundle: None, installed_at: None }
    }

    #[test]
    fn matches_by_token_prefix_and_name() {
        assert!(find(&app("formula:docker-compose", "docker-compose")).is_some());
        assert!(find(&app("formula:openjdk@17", "openjdk@17")).is_some());
        assert!(find(&app("cask:flutter", "Flutter SDK")).is_some());
        assert!(find(&app("formula:golangci-lint", "golangci-lint")).is_some());
        assert!(find(&app("formula:zzz-unknown", "zzz-unknown")).is_none());
    }

    #[test]
    fn every_logo_decodes() {
        for (names, png) in LOGOS {
            assert!(crate::icons::decode_bytes(png).is_some(), "{names:?}");
        }
    }
}
